test("watch and notify scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "perm-open", "clerk");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-01", "to": "2026-04-02"})).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  await ui.setToday(pg_uma, "2026-04-13");
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.hold(pg_wes, p_ada, {"from": "2026-02-25", "to": "2026-03-09"})).toBe(true);
  expect(await ui.statement(pg_wes, p_ada)).toBe(true);
  const c_cam_1 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "10.35", "date": "2026-03-15"}));
  expect(await ui.statement(pg_wes, p_cam)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("12.50");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("12.50");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
