import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupSnapshot;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Settles each selected claim in list order — the people in the order they were added, each one's claims newest
 * first. Each is settled exactly as settling it alone would (the same refusals, the same audit and rollup lines);
 * one a clerk's settle leaves PENDING counts as settled, one that cannot be settled is left as it is and counted as
 * refused.
 */
public class SettleClaims {
    public void settle(@Val SheetResponse sheet, @Val BulkSettleIds selected, @Val ChangedBy by, ClaimRepository claims,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, PeriodRepository periods, Rollup rollup, Audit audit, ClaimLog log,
            Out<BulkSettleResponse> result) {
        int settled = 0;
        if (roles.isViewer(sheet.id(), by.name())) {
            // A viewer's press goes through with nothing done: every selected claim is refused.
            result.set(new BulkSettleResponse(0, selected.ids().size()));
            return;
        }
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RefuseClosedClaim closed = new RefuseClosedClaim();
        RecordClaimStatus record = new RecordClaimStatus();
        for (Person person : people.list(sheet.id())) {
            for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
                if (!selected.ids().contains(claim.getId())) {
                    continue;
                }
                try {
                    closed.check(claim, periods);
                    RollupSnapshot before = rollup.snapshot(sheet.id());
                    ClaimNumber[] number = new ClaimNumber[1];
                    Out<ClaimNumber> audited = value -> number[0] = value;
                    apply.apply(ClaimStatus.SETTLED, claim, claims, people, rates, roles, settings, sheets, periods, by, ClaimReview.NONE, audited);
                    record.record(claim, number[0], by, ClaimReview.NONE, people, audit, log);
                    rollup.record(sheet.id(), before, by);
                    settled++;
                } catch (BadRequestException refused) {
                    // left as it is
                }
            }
        }
        // A selected id not on this sheet's list cannot be settled either.
        result.set(new BulkSettleResponse(settled, selected.ids().size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.session.ChangedBy;

/**
 * A claim's audit record: the event, sheet, user, then person, amount (two decimals) and date, and
 * the claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    static String line(String event, Claim claim, ChangedBy by, String personName) {
        return line(event, claim, by, personName, claim.getNumber());
    }

    static String line(String event, Claim claim, ChangedBy by, String personName, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + by.name() + " person=" + personName + " amount="
                + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.session;

import net.officefloor.hq.app.BadRequestException;

/** The signed-in user a change is made by, as sent with the change; the audit records it. */
public record ChangedBy(String name) {

    /** The trimmed user, refusing a change sent without one. */
    public static ChangedBy of(String by) throws BadRequestException {
        String name = by == null ? "" : by.trim();
        if (name.isEmpty()) {
            throw new BadRequestException("Sign in to make a change");
        }
        return new ChangedBy(name);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonHold {
    public void record(@Val Person person, @Val HoldSpan hold, @Val ChangedBy by, Audit audit) {
        audit.record("PERSON_HELD sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " from=" + hold.from());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds a hold to the person, from its from-date (blank: the sheet's today) to its to-date; refuses one ending before it starts. */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Person person, PersonRepository repository, SheetRepository sheets,
            Out<HoldSpan> added) throws BadRequestException {
        LocalDate from = input.from() != null ? input.from() : sheets.today(person.getSheetId());
        if (input.to() != null && input.to().isBefore(from)) {
            throw new BadRequestException("A hold's to-date cannot be before its from-date");
        }
        HoldSpan hold = new HoldSpan(from, input.to());
        repository.addHold(person.getId(), hold);
        List<HoldSpan> holds = new ArrayList<>(person.getHolds());
        holds.add(hold);
        person.setHolds(holds);
        added.set(hold);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@Val SheetResponse sheet, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws BadRequestException {
        Person found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (found == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        person.set(found);
    }
}

