import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/people.slot';
import { personActionKey, useLastPersonAction } from '../people/personAction';
import { useUser } from '../session/useSession';

function HoldHeads() {
  return (
    <>
      <th>On hold</th>
      <th>Holds</th>
      <th />
    </>
  );
}

// Whether the person has any hold, their holds (each from its from-date to its to-date, none: open-ended), and the
// dates and button that add one (a blank from-date: the sheet's today). Their OPEN and PENDING claims dated within a
// hold count in no live total unless a statement binds them; a hold ends on its to-date, there is no release. A
// refusal shows on the person until the next action on their row.
function HoldCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const person = usePeople(sheetId).data?.find((p) => p.id === personId);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const hold = useMutation({
    mutationKey: personActionKey(sheetId, personId),
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, {
        from: dates.from.trim(),
        to: dates.to.trim(),
        by: user ?? '',
      }),
    onSuccess: async () => {
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const last = useLastPersonAction(sheetId, personId, hold.submittedAt);

  return (
    <>
      <td data-testid="person-hold">{person?.held ? 'yes' : 'no'}</td>
      <td>
        {(person?.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from ?? '…'} – {h.to ?? '…'}
          </div>
        ))}
      </td>
      <td>
        <input
          type="date"
          data-testid="person-hold-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          type="date"
          data-testid="person-hold-to"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button type="button" data-testid="person-hold-toggle" disabled={hold.isPending} onClick={() => hold.mutate({ from, to })}>
          Hold
        </button>
        {hold.isError && last && (
          <span data-testid="person-error" role="alert">
            {hold.error.message}
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 45, Component: HoldHeads }),
  PersonCells.fill({ order: 45, Component: HoldCells }),
];
import { useMutationState } from '@tanstack/react-query';

/** The key every action on a person's row (a statement, a retirement) runs its mutation under, so the row shows
 *  one error at a time: the last action's. */
export const personActionKey = (sheetId: string, personId: number) => ['sheet', sheetId, 'person-action', personId] as const;

/** Whether the mutation (run under personActionKey) is the last action taken on the person's row: only that
 *  one's refusal shows, so the next action on the row removes the error of the one before. */
export function useLastPersonAction(sheetId: string, personId: number, submittedAt: number): boolean {
  const times = useMutationState({
    filters: { mutationKey: personActionKey(sheetId, personId) },
    select: (m) => m.state.submittedAt,
  });
  return submittedAt === Math.max(0, ...times);
}
import { defineSlot } from '../Slot';

/**
 * Extra columns of the people table. A contribution renders one `<th>` in the header slot and one
 * `<td>` per person in the cells slot, at the same order, so the columns line up.
 */
export const PersonHeads = defineSlot<{ sheetId: string; user: string }>('person.heads');
export const PersonCells = defineSlot<{ sheetId: string; user: string; personId: number }>('person.cells');
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { toHundredths, type Late } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';
import { useClaims } from '../claims/useClaims';

/** A role assigned to a user name: clerk (any name without one), steward or viewer. */
export type Role = { user: string; role: string };

/** A sheet setting: its value in force on the sheet's today (null: blank) and, for a dated one, every value recorded
 *  by from-date (yyyy-mm-dd), each in force until the next one's. */
export type Setting = { key: string; value: string | null; dated: { from: string; value: string | null }[] };

/** A dated setting's value in force on a date (yyyy-mm-dd): the one with the latest from-date on or before it; before
 *  every from-date (or when blank), `starting`. */
export function settingOn(setting: Setting | undefined, date: string, starting: string): string {
  let found: { from: string; value: string | null } | undefined;
  for (const d of setting?.dated ?? []) {
    // ISO dates compare as text.
    if (d.from <= date && (found === undefined || d.from > found.from)) found = d;
  }
  return found?.value ?? starting;
}

export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;
export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The sheet's assigned roles, by user name. */
export function useRoles(sheetId: string) {
  return useQuery({
    queryKey: rolesKey(sheetId),
    queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
  });
}

/** The floor a sheet starts with, until it is set. */
export const FLOOR_DEFAULT = '1.00';

/** The sheet's settings, by key. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Setting[]>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor in cents in force on a date: the least a claim's live due may be (1.00 before any is in force). */
export type FloorOn = (date: string) => bigint;

/** The sheet's floor in cents, by the date it is in force on. */
export function useFloorCents(sheetId: string): FloorOn {
  const floor = useSettings(sheetId).data?.find((s) => s.key === 'floor');
  return (date) => toHundredths(settingOn(floor, date, FLOOR_DEFAULT));
}

/** The sheet's cap in cents in force on its today: the most a person's due-total may be; null while blank (no cap). */
export function useCapCents(sheetId: string): bigint | null {
  const value = useSettings(sheetId).data?.find((s) => s.key === 'cap')?.value;
  return value == null || value === '' ? null : toHundredths(value);
}

/** The terms a sheet starts with, until they are set: the days after its date a claim is due by. */
export const TERMS_DEFAULT = '14';

/** The late percent a sheet starts with, until it is set. */
export const LATE_PCT_DEFAULT = '0.00';

/** The sheet's late charge as of its today: its late percent in force on each date (0.00 before any is); with its
 *  policy date (its today while blank) and the numbered claims' dates, which decide how each claim rounds. Undefined
 *  until the sheet's today is known. */
export function useLate(sheetId: string): Late | undefined {
  const settings = useSettings(sheetId).data;
  const pct = settings?.find((s) => s.key === 'late-pct');
  const policy = settings?.find((s) => s.key === 'policy-date')?.value ?? '';
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId).data;
  const dateOfNumber = new Map<string, string>();
